-- MIGRATION_KIND: mixed
-- SAFETY: Additive profession catalog and JSONB secondary-professions field. Existing staff.role_type remains the primary grouping source; seed rows are idempotent through ON CONFLICT.
-- ROLLBACK: Export hr_professions and staff.secondary_professions if needed, then DROP TABLE hr_professions and DROP COLUMN staff.secondary_professions.

ALTER TABLE staff
    ADD COLUMN IF NOT EXISTS secondary_professions JSONB NOT NULL DEFAULT '[]'::jsonb;

UPDATE staff
SET secondary_professions = '[]'::jsonb
WHERE secondary_professions IS NULL
   OR jsonb_typeof(secondary_professions) <> 'array';

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'staff_secondary_professions_is_array'
    ) THEN
        ALTER TABLE staff
            ADD CONSTRAINT staff_secondary_professions_is_array
            CHECK (jsonb_typeof(secondary_professions) = 'array') NOT VALID;
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS hr_professions (
    id SERIAL PRIMARY KEY,
    key VARCHAR(64) NOT NULL UNIQUE,
    title VARCHAR(120) NOT NULL,
    department VARCHAR(80),
    short_info TEXT,
    responsibilities JSONB NOT NULL DEFAULT '[]'::jsonb,
    checklist JSONB NOT NULL DEFAULT '[]'::jsonb,
    color VARCHAR(20),
    sort_order INTEGER NOT NULL DEFAULT 100,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_hr_professions_active_sort
    ON hr_professions(is_active, sort_order, title);

